/* @lc app=leetcode id=2872 lang=kotlin */ class Solution { fun maxKDivisibleComponents(n: Int, edges: Array<IntArray>, values: IntArray, k: Int): Int = edges.flatMap { (a, b) -> listOf(a to b, b to a) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { par[it] == -1 }.onEach { v -> par[v] = u } }.takeIf { it.isNotEmpty() } }.flatten().toList().reversed().let { order -> LongArray(n) { values[it].toLong() }.let { s -> order.count { v -> (s[v] % k == 0L).also { z -> if (!z && v != 0) s[par[v]] += s[v] } } } } } } }